diff --git a/server/services/reviews/apply.ts b/server/services/reviews/apply.ts
index 3561dfe..7bc985f 100644
--- a/server/services/reviews/apply.ts
+++ b/server/services/reviews/apply.ts
@@ -472,12 +472,151 @@ function deleteBranchEverywhere(target: RepoIntegrationTarget, branch: string):
  * who followed it literally. `target-main-missing` is included for
  * completeness (the function does have that return path) even though it is
  * not one of the 3 causes this round's finding named explicitly.
+ *
+ * `unsafe-skill-name`/`graft-failed` are specific to the Chemin A CONTENT-
+ * REPLACEMENT strategy (`graftSkillContent`, see its own docstring and
+ * `docs/evals/rail-application.md`) added once real `improve/<skill>-<date>`
+ * branches from the cloud routine were found to have NO common ancestor with
+ * `claude-skills` (verified 2026-07-29 via `git merge-base`, chip
+ * `2026-07-29-fix-git-merge-unrelated-histories-failure-in-apply-ts-rail`).
  */
 export type MergeFailureCause =
   | 'before-sha-mismatch'
   | 'branch-missing'
   | 'merge-conflict'
-  | 'target-main-missing';
+  | 'target-main-missing'
+  | 'unsafe-skill-name'
+  | 'graft-failed';
+
+/**
+ * Chemin A's merge strategy — CONTENT REPLACEMENT, not `git merge`. Full
+ * rationale in `docs/evals/rail-application.md`; short version: every
+ * `improve/<skill>-<date>` branch produced by the cloud routine today is a
+ * SNAPSHOT of the skill's desired final file state, built fresh on the cloud
+ * side (`docs/evals/routine-cloud-prompt.md`'s own words: "changedPaths[] (la
+ * liste des fichiers touchés, pas un patch unifié brut)") — never a commit
+ * layered on top of a real clone of `target.remote`'s history. Confirmed
+ * empirically 2026-07-29: `git merge-base` between a real `improve/*` branch
+ * and `claude-skills@main` returns nothing.
+ *
+ * A plain `git merge --allow-unrelated-histories` would either refuse
+ * outright (no flag) or, WITH the flag, merge the branch's ENTIRE tree —
+ * including anything it carries OUTSIDE `<skill>/`, whether by cloud bug or a
+ * compromised routine. That is exactly the security regression this design
+ * avoids: instead of asking git's 3-way-merge machinery to reconcile two
+ * unrelated trees, this function replaces ONLY `<proposal.skill>/` in
+ * `main`'s tree with `<proposal.skill>/` as it exists at the tip of `branch`
+ * — nothing else on `main` can ever be touched by this function, no matter
+ * what the branch contains elsewhere. `git rm -r` (drop the skill folder's
+ * current content from the index) + `git checkout <branch> -- <skill>/`
+ * (restore it from the branch tip — works regardless of ancestry, `checkout
+ * -- <pathspec>` reads tree objects directly and never consults history) +
+ * `git add -A` builds the new tree; `git write-tree` + `git commit-tree -p
+ * <mainSha> -p <branchSha>` then hand-builds a real TWO-PARENT commit so the
+ * result is indistinguishable, to every other piece of this file, from a
+ * normal `--no-ff` merge commit — in particular `revertMergeCommitOnMain`'s
+ * `git revert -m 1`, which requires an actual merge commit to work at all
+ * (verified empirically against a hand-built `commit-tree` merge commit
+ * before wiring this in).
+ *
+ * Path-safety guard duplicated here (not just relied upon downstream in
+ * `installSkillFromIntegrationClone`): this function is the FIRST place a
+ * path derived from `proposal.skill` is used destructively (`git rm -r`)
+ * against the REAL `target.remote`, earlier than the local install step —
+ * without this guard, a skill name that is git-ref-SAFE (e.g. contains `/`,
+ * which git allows in a ref but `isSafeSegment` rejects as a directory
+ * traversal risk) could reach `git rm -r`/`git checkout -- <path>` here and
+ * mutate the REAL remote's `main` before the local-install guard ever got a
+ * chance to refuse it.
+ */
+function graftSkillContent(
+  proposal: ImprovementProposal,
+  target: RepoIntegrationTarget,
+  branch: string,
+  mainSha: string,
+  branchSha: string,
+): { ok: true; mergeSha: string } | { ok: false; reason: string; cause: MergeFailureCause } {
+  const cwd = target.integrationClone;
+
+  if (
+    !isSafeSegment(proposal.skill) ||
+    proposal.skill === '.' ||
+    path.posix.normalize(proposal.skill) === '.' ||
+    path.posix.normalize(proposal.skill) === ''
+  ) {
+    return {
+      ok: false,
+      cause: 'unsafe-skill-name',
+      reason:
+        'nom de skill non sûr pour une opération fichier (traversée de chemin, séparateur, ou segment ' +
+        `"." qui résoudrait le chemin greffé à la racine du dépôt) : ${JSON.stringify(proposal.skill)} — ` +
+        'greffe refusée avant tout git rm/checkout sur le remote réel',
+    };
+  }
+  const skillPath = `${proposal.skill}/`;
+
+  // Drop whatever `<skill>/` currently holds on `main` — `--ignore-unmatch`:
+  // a brand-new skill with no prior folder on main is not an error.
+  const rmResult = gitTry(['rm', '-r', '--ignore-unmatch', '-q', '--', skillPath], cwd);
+  if (!rmResult.ok) {
+    git(['reset', '--hard', mainSha], cwd);
+    return {
+      ok: false,
+      cause: 'graft-failed',
+      reason: `git rm -r ${skillPath} a échoué dans ${cwd} : ${rmResult.stderr || rmResult.stdout || 'sortie vide'}`,
+    };
+  }
+
+  // Restore `<skill>/` from the branch tip. A missing path on the branch
+  // (checked first, via `rev-parse --verify`, so we never conflate "path
+  // absent" with a real git error) means the branch legitimately deletes the
+  // whole skill folder — the `git rm` above already recorded that; nothing
+  // more to do for this path.
+  const branchHasPath = gitTry(['rev-parse', '--verify', '--quiet', `${branch}:${skillPath}`], cwd).ok;
+  if (branchHasPath) {
+    const checkoutResult = gitTry(['checkout', branch, '--', skillPath], cwd);
+    if (!checkoutResult.ok) {
+      git(['reset', '--hard', mainSha], cwd);
+      return {
+        ok: false,
+        cause: 'graft-failed',
+        reason:
+          `git checkout ${branch} -- ${skillPath} a échoué dans ${cwd} : ` +
+          (checkoutResult.stderr || checkoutResult.stdout || 'sortie vide'),
+      };
+    }
+  }
+
+  const addResult = gitTry(['add', '-A', '--', skillPath], cwd);
+  if (!addResult.ok) {
+    git(['reset', '--hard', mainSha], cwd);
+    return {
+      ok: false,
+      cause: 'graft-failed',
+      reason: `git add -A ${skillPath} a échoué dans ${cwd} : ${addResult.stderr || addResult.stdout || 'sortie vide'}`,
+    };
+  }
+
+  try {
+    const treeSha = gitOut(['write-tree'], cwd);
+    const commitMessage =
+      `merge: ${branch} (proposal ${proposal.id}) — remplacement de contenu scellé à ${skillPath} ` +
+      '(la branche cargo est un instantané, pas un diff sur l\'historique cible — voir docs/evals/rail-application.md)';
+    const commitSha = gitOut(
+      ['commit-tree', treeSha, '-p', mainSha, '-p', branchSha, '-m', commitMessage],
+      cwd,
+    );
+    git(['reset', '--hard', commitSha], cwd);
+    return { ok: true, mergeSha: commitSha };
+  } catch (err) {
+    git(['reset', '--hard', mainSha], cwd);
+    return {
+      ok: false,
+      cause: 'graft-failed',
+      reason: `construction du commit de greffe pour ${skillPath} a échoué dans ${cwd} : ${(err as Error).message}`,
+    };
+  }
+}

